#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=9
ENV_FILE="${RELEASE_ENV_FILE:-deploy/.env.release}"
ACCEPTANCE_ENV="deploy/.env.acceptance"
RELEASE_LOG="${RELEASE_LOG:-.scratch/mvp-release/release-runs/$(date +%F).md}"
SSH_OPTS=(-o ConnectTimeout=10 -o BatchMode=yes)

REPO_ROOT="$(git rev-parse --show-toplevel 2>/dev/null || pwd)"
cd "$REPO_ROOT"
mkdir -p "$(dirname "$RELEASE_LOG")"
touch "$ENV_FILE"; chmod 600 "$ENV_FILE"
[[ -f "$RELEASE_LOG" ]] || printf '# 发布记录 %s\n\n' "$(date +%F)" > "$RELEASE_LOG"

record() { printf -- '- %s — %s\n' "$1" "$2" >> "$RELEASE_LOG"; }
have_gh() { command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; }
abort() { _clear; warn "$1"; say "已完成的步骤记录在 $RELEASE_LOG"; printf '\n'; exit 0; }
acceptance_value() { [[ -f "$ACCEPTANCE_ENV" ]] && sed -n "s/^$1=//p" "$ACCEPTANCE_ENV" | tail -n1 || true; }
seed_acceptance() {
  local v; v="$(acceptance_value "$1")"
  [[ -n "$v" && -z "$(_existing "$1" || true)" ]] && write_env "$1" "$v"
  return 0
}
expect_code() {
  local label="$1" expected="$2" url="$3" code
  code=$(curl -s -o /dev/null -w '%{http_code}' --max-time 10 "$url" 2>/dev/null || true)
  if [[ "$code" == "$expected" ]]; then
    say "  ${GREEN}✓${RESET} $label ($code)"; record "冒烟" "$label PASS ($code)"
  else
    warn "$label 期望 ${expected}，实际 ${code:-无响应}"; record "冒烟" "$label FAIL (期望 $expected，实际 ${code:-无响应})"
  fi
}

banner "云河FC 生产发布 · 主线向导"

# ── Stage 1 ───────────────────────────────────────────────────────────────
stage "预检与回滚预案"
say "检查本地状态、发布窗口与回滚出口。"
branch=$(git rev-parse --abbrev-ref HEAD)
if [[ "$branch" != "qua" ]]; then
  abort "当前分支是 $branch，发布必须从 qua 发起。"
fi
say "  ✓ 当前分支 qua"
dirty=$(git status --porcelain | grep -v '^??' || true)
if [[ -n "$dirty" ]]; then
  warn "工作区有未提交改动："; printf '%s\n' "$dirty"
  confirm "忽略并继续？" || abort "请先提交或清理工作区。"
else
  say "  ✓ 工作区干净"
fi
git fetch --prune origin || abort "git fetch 失败，检查网络与远端。"
counts=$(git rev-list --left-right --count origin/qua...HEAD)
behind=${counts%%[[:space:]]*}; ahead=${counts##*[[:space:]]}
[[ "$behind" == "0" ]] || warn "落后 origin/qua $behind 个提交"
say "  待合并到 main：$ahead 个提交"
seed_acceptance RC_DOMAIN
seed_acceptance ECS_SSH
ask CUTOVER_AT "cutover 时间（YYYY-MM-DD HH:MM，工作日 20:00 后）："
ask RELEASE_NOTE "发布备注（写入 deploy.yml 与通知）："
write_env CUTOVER_AT "$CUTOVER_AT"
write_env RELEASE_NOTE "$RELEASE_NOTE"
{
  printf '## 发布 %s\n\n' "$(date '+%F %T')"
  printf -- '- cutover_at: %s\n- note: %s\n\n' "$CUTOVER_AT" "$RELEASE_NOTE"
} >> "$RELEASE_LOG"
warn "硬门槛：main 冻结 ≥24h、112 条签收、回滚演练、RDS 备份口径。"
if ! confirm "以上前置已确认（或已按 §10 接受风险）？"; then
  abort "按 release-checklist §0.1，硬门槛未过不得继续。"
fi
say "回滚出口（命中 readiness/5xx/关键路径异常时 15 分钟内执行）："
note "ssh $ECS_SSH '/opt/yunhefc/current/bin/release.sh --rollback'"
record "预检" "branch=$branch ahead=$ahead cutover=$CUTOVER_AT"

# ── Stage 2 ───────────────────────────────────────────────────────────────
stage "小程序 P-78~P-82 真机验收"
say "逐票确认开发者工具 / 真机结果；任一未过先不要发版。"
failed=0
for ticket in \
  "P-78 比赛详情：报名 / 取消 / 候补递补" \
  "P-79 签到与名单考勤" \
  "P-80 事件录入与本人编辑" \
  "P-81 管理员状态修改与首页入口" \
  "P-82 我的页移除找回密码入口"; do
  if confirm "$ticket 已通过？"; then
    record "真机验收" "$ticket PASS"
  else
    failed=$((failed + 1)); record "真机验收" "$ticket FAIL"
  fi
done
if (( failed > 0 )); then
  warn "$failed 票未通过"
  confirm "仍继续发版？" || abort "先完成小程序验收再发。"
fi

# ── Stage 3 ───────────────────────────────────────────────────────────────
stage "创建 qua→main PR"
have_gh || abort "gh 未安装或未登录：先 gh auth login 再重跑。"
PR_NUMBER="$(gh pr list --head qua --base main --state open --json number -q '.[0].number' 2>/dev/null || true)"
if [[ -n "$PR_NUMBER" ]]; then
  say "复用已有 PR #$PR_NUMBER"
  PR_URL="$(gh pr view "$PR_NUMBER" --json url -q .url)"
else
  say "将合并的提交："
  git log --oneline origin/main..qua | sed 's/^/    /'
  say "改动规模（前 5 行）："
  git diff --stat origin/main...qua | tail -n 5 | sed 's/^/    /'
  ask PR_TITLE "PR 标题（留空用默认）："
  [[ -n "$PR_TITLE" ]] || PR_TITLE="release: 小程序验收与发布 $(date +%F)"
  PR_BODY="$(printf '## 发布\n- cutover: %s\n- note: %s\n\n检查单：`.scratch/mvp-release/release-checklist.md`\n\n合并前确认 CI 全绿；镜像 tag 取 main 合并提交 sha7。\n' "$CUTOVER_AT" "$RELEASE_NOTE")"
  confirm "创建 PR？" || abort "未创建 PR。"
  PR_URL="$(gh pr create --base main --head qua --title "$PR_TITLE" --body "$PR_BODY")" \
    || abort "创建 PR 失败。"
  PR_NUMBER="$(gh pr view "$PR_URL" --json number -q .number)"
fi
write_env PR_URL "$PR_URL"
say "  ✓ $PR_URL"
record "PR" "$PR_URL"
open_url "$PR_URL"
pause "检查 PR 内容后回车"

# ── Stage 4 ───────────────────────────────────────────────────────────────
stage "合并 PR（红线）"
say "先等 PR CI 全绿："
if gh pr checks "$PR_NUMBER" --watch; then
  say "  ✓ PR 检查全绿"
else
  warn "PR 检查未全绿"
  confirm "仍要合并？" || abort "CI 未过，不合并。"
fi
head_sha7=$(git rev-parse --short=7 origin/qua)
say "PR head：$head_sha7（注意：部署 tag 用合并后的 main 提交）"
confirm "确认合并到 main？此操作会触发 main CI 与镜像构建。" || abort "未合并。"
gh pr merge "$PR_NUMBER" --merge || abort "合并失败（冲突或检查未过）。"
git fetch --prune origin main || abort "合并后 fetch main 失败。"
MERGE_SHA7=$(git rev-parse --short=7 origin/main)
write_env MERGE_SHA7 "$MERGE_SHA7"
say "  ✓ main 合并提交：$MERGE_SHA7"
record "合并" "PR #$PR_NUMBER → main $MERGE_SHA7（PR head $head_sha7）"

# ── Stage 5 ───────────────────────────────────────────────────────────────
stage "等待 main 镜像产出"
say "查找 main 上 $MERGE_SHA7 的 CI run；images job 产出 sha-$MERGE_SHA7。"
run_id=""
for _ in $(seq 1 12); do
  run_id=$(gh run list --workflow ci.yml --branch main --limit 10 --json databaseId,headSha \
    -q ".[] | select(.headSha | startswith(\"$MERGE_SHA7\")) | .databaseId" | head -n1)
  [[ -n "$run_id" ]] && break
  sleep 10
done
[[ -n "$run_id" ]] || abort "未找到 main 上 $MERGE_SHA7 的 CI run。"
run_url="$(gh run view "$run_id" --json url -q .url)"
open_url "$run_url"
say "等待 CI（含 images job，上限 40 分钟）。"
if ! gh run watch "$run_id" --exit-status; then
  abort "main CI 失败，不要部署；修复后重新走合并流程。"
fi
imgs=$(gh run view "$run_id" --json jobs -q '.jobs[] | select(.name=="images") | .conclusion')
[[ "$imgs" == "success" ]] || abort "images job 未成功（${imgs:-unknown}）。"
say "  ✓ images job 成功，镜像 tag：sha-$MERGE_SHA7"
record "镜像" "$run_url images=success"

# ── Stage 6 ───────────────────────────────────────────────────────────────
stage "触发生产部署（红线）"
say "将执行："
note "gh workflow run deploy.yml --ref main -f sha=$MERGE_SHA7 -f note=\"$RELEASE_NOTE\""
warn "需要 production Environment 人工审批；失败不自动回滚。"
confirm "确认触发生产部署？" || abort "未部署。"
gh workflow run deploy.yml --ref main -f sha="$MERGE_SHA7" -f note="$RELEASE_NOTE" \
  || abort "触发 deploy.yml 失败（确认 --ref main 与仓库权限）。"
sleep 5
deploy_run=""
for _ in $(seq 1 6); do
  deploy_run=$(gh run list --workflow deploy.yml --limit 10 --json databaseId,headSha \
    -q ".[] | select(.headSha | startswith(\"$MERGE_SHA7\")) | .databaseId" | head -n1)
  [[ -n "$deploy_run" ]] && break
  sleep 5
done
[[ -n "$deploy_run" ]] || abort "未找到本次 deploy run，请到 Actions 页面核对。"
deploy_url="$(gh run view "$deploy_run" --json url -q .url)"
write_env DEPLOY_RUN_URL "$deploy_url"
open_url "$deploy_url"
say "等待 Environment 审批与部署（timeout 20 分钟）。"
if ! gh run watch "$deploy_run" --exit-status; then
  warn "部署失败"
  say "回滚：ssh $ECS_SSH '/opt/yunhefc/current/bin/release.sh --rollback'"
  if confirm "现在执行回滚？"; then
    ssh "${SSH_OPTS[@]}" "$ECS_SSH" '/opt/yunhefc/current/bin/release.sh --rollback' \
      || warn "回滚命令失败，按 RUNBOOK §2 手工处置。"
  fi
  abort "部署失败，已按选择处置；保留现场后再分析。"
fi
say "  ✓ 部署完成：$deploy_url"
record "部署" "$deploy_url success"

# ── Stage 7 ───────────────────────────────────────────────────────────────
stage "部署冒烟"
seed_acceptance RC_DOMAIN
seed_acceptance ECS_SSH
while :; do
  ask RC_DOMAIN "生产域名（不含 www）："
  if [[ "$RC_DOMAIN" =~ ^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$ ]] \
      && [[ "$RC_DOMAIN" != www.* ]]; then
    break
  fi
  warn "域名必须是小写裸域名（如 example.com），不带 scheme/路径/端口"
  write_env RC_DOMAIN ""
done
ask ECS_SSH "ECS SSH 目标（user@host）："
WEB="https://www.$RC_DOMAIN"
export NO_PROXY="${NO_PROXY:+$NO_PROXY,}www.$RC_DOMAIN,$RC_DOMAIN"
export no_proxy="$NO_PROXY"

health=$(curl -fsS --max-time 10 "$WEB/actuator/health" 2>/dev/null || true)
if [[ "$health" == *'"status":"UP"'* ]]; then
  say "  ${GREEN}✓${RESET} readiness = UP"; record "冒烟" "readiness UP"
else
  warn "readiness 未返回 UP"; record "冒烟" "readiness FAIL"
fi
expect_code "C 端首页 200" "200" "$WEB/"
expect_code "B 端 /admin/ 200" "200" "$WEB/admin/"
expect_code "公开读接口 200" "200" "$WEB/api/v1/c/matches?scope=upcoming&page=1&pageSize=1"
expect_code "敏感端点 /actuator/env 404" "404" "$WEB/actuator/env"
mini_code=$(curl -s -o /dev/null -w '%{http_code}' -X POST -H 'Content-Type: application/json' \
  -d '{"code":""}' --max-time 10 "$WEB/api/v1/c/auth/mini/login" 2>/dev/null || true)
if [[ "$mini_code" == "400" ]]; then
  say "  ${GREEN}✓${RESET} 小程序登录端点拒绝空 code（400）"; record "冒烟" "小程序登录端点 PASS"
else
  warn "小程序登录端点期望 400，实际 ${mini_code:-无响应}"; record "冒烟" "小程序登录端点 FAIL"
fi
current=$(ssh "${SSH_OPTS[@]}" "$ECS_SSH" 'readlink -f /opt/yunhefc/current' 2>/dev/null || true)
if [[ "$current" == *"/releases/$MERGE_SHA7" ]]; then
  say "  ${GREEN}✓${RESET} current → $current"; record "冒烟" "current 指向 $MERGE_SHA7"
else
  warn "current 指向 ${current:-未知}，期望 releases/$MERGE_SHA7"; record "冒烟" "current FAIL"
fi
unhealthy=$(ssh "${SSH_OPTS[@]}" "$ECS_SSH" \
  "docker ps --format '{{.Names}} {{.Status}}' | grep -i unhealthy || true" 2>/dev/null || true)
if [[ -z "$unhealthy" ]]; then
  say "  ${GREEN}✓${RESET} 无 unhealthy 容器"; record "冒烟" "容器健康 PASS"
else
  warn "unhealthy 容器：$unhealthy"; record "冒烟" "容器健康 FAIL"
fi

# ── Stage 8 ───────────────────────────────────────────────────────────────
stage "RC 验收"
say "运行只读验收向导：scripts/rc-acceptance-wizard.sh"
say "它会追加结果到 deploy/rc-acceptance-results.md。"
before=$(wc -l < deploy/rc-acceptance-results.md 2>/dev/null || echo 0)
confirm "现在运行 RC 验收？" || abort "稍后手工执行：bash scripts/rc-acceptance-wizard.sh"
bash scripts/rc-acceptance-wizard.sh || warn "RC 向导返回非 0，检查结果文件"
section=$(tail -n +$((before + 1)) deploy/rc-acceptance-results.md 2>/dev/null || true)
fails=$(printf '%s\n' "$section" | grep -c 'FAIL' || true)
passes=$(printf '%s\n' "$section" | grep -c 'PASS' || true)
say "本轮记录：PASS $passes / FAIL $fails"
record "RC 验收" "PASS=$passes FAIL=$fails"
if (( fails > 0 )); then
  warn "存在 FAIL 项"
  confirm "仍继续签收？" || abort "先处置 FAIL 项，再重跑本向导。"
fi

# ── Stage 9 ───────────────────────────────────────────────────────────────
stage "观测与签收"
say "T+30 分钟判定；任一异常 → 15 分钟内回滚："
step "5xx：发布后 30 分钟是否异常升高"
step "登录：成功率是否明显下降 / 连续 401、429"
step "报名：非业务预期错误是否集中出现"
step "通知：是否有新通知 / 积压是否持续增长"
step "资源：容器无 unhealthy；磁盘 >75%、内存 >90%、Kafka lag >1000、Outbox >500"
note "ssh $ECS_SSH 'docker ps --format \"{{.Names}} {{.Status}}\"'"
if ! confirm "以上指标无异常，判定保持？"; then
  warn "执行回滚：ssh $ECS_SSH '/opt/yunhefc/current/bin/release.sh --rollback'"
  abort "已停止签收。"
fi
say "在队伍群公告放行，并登记 T+24h / T+72h 复查。"
if confirm "已公告并登记复查点？"; then
  record "签收" "cutover=$CUTOVER_AT sha=$MERGE_SHA7 观测通过"
else
  warn "未确认公告；请在群内补发并登记复查点。"
fi
cat >> "$RELEASE_LOG" <<EOF

## 签收 $(date '+%F %T')

- cutover: $CUTOVER_AT
- note: $RELEASE_NOTE
- main sha7: $MERGE_SHA7
- PR: $PR_URL
- 部署: ${deploy_url:-未记录}
- RC 结果: deploy/rc-acceptance-results.md
- 回滚: ssh $ECS_SSH '/opt/yunhefc/current/bin/release.sh --rollback'
- 复查: T+24h、T+72h
EOF
# ──────────────────────────────────────────────────────────────────────────

finish
note "发布记录：$RELEASE_LOG"
